// Generated by scripts/authoring-reference.mjs from the built declarations — do not edit.
// The types are the reference: run `pnpm build && node scripts/authoring-reference.mjs` after
// changing anything under src/authoring, and the test of the same name fails until you do.
export const AUTHORING_REFERENCE: ReadonlyArray<{ readonly title: string; readonly body: string }> =
	[
		{
			"title": "Server api",
			"body": "export type Api<S extends AnySchema = DefaultWorkspaceSchema> = {\n    /** Reads. Writes go through `collection`. */\n    readonly db: AuthoredReadDatabase<S>;\n    /** The declared write surface (RFC §4.2), one entry per `+collection.ts`. */\n    readonly collection: AuthoredCollectionsApi<S>;\n    readonly collection_history: AuthoredCollectionHistory<S>;\n    /**\n     * Manually run a declared automation from code, in the background, with retry.\n     *\n     * Every automation has this manual entry point. `defineAutomation({ schedule })` additionally\n     * starts it on a clock, `defineAutomation({ trigger })` additionally starts it when a record\n     * changes, and `defineAutomation({})` has no automatic start. This is the entry point an author\n     * previously had no way to say, and the alternatives were both bad: a hook must either fail the\n     * user's write or swallow the error, and a change trigger is lost if it throws.\n     *\n     * There is deliberately no `api.tasks`. A task is not a thing an author has — it is how the\n     * runtime carries out something the workspace already declared — and a second way to start\n     * background work would compete with the automations that declaration produces. Two ways to say\n     * one thing is one too many.\n     *\n     * `after` takes any duration this codebase takes: `'1 hour'`, `'30 seconds'`, or milliseconds.\n     * Omitted, the automation runs as soon as the queue can take it.\n     */\n    readonly automations: {\n        readonly run: (name: string, input?: Schema.Json, options?: {\n            readonly after?: string | number;\n        }) => Effect.Effect<{\n            readonly taskId: string;\n        }>;\n    };\n    readonly infer: <Output>(input: StructuredInferenceInput<Output>) => Effect.Effect<Output>;\n    readonly readFileAsset: (file: FileRef) => Effect.Effect<{\n        readonly id: string;\n        readonly name: string;\n        readonly mimeType: string | null;\n        readonly size: number;\n        readonly bytes: Uint8Array;\n    }>;\n    /**\n     * Fills missing platform record embeddings for one collection, host-side.\n     *\n     * A record embedding is a platform column, so no authored write can set it: the host reads the\n     * collection's `search: true` columns, resolves a file column into its image, embeds, and\n     * writes the vector. One call is bounded and re-runnable — it selects only rows that have none —\n     * so a scheduled pass loops until `selected` is zero. `ids` narrows the pass to named rows.\n     */\n    readonly embed: (input: {\n        readonly collection: TableName<S>;\n        readonly ids?: ReadonlyArray<string>;\n        readonly limit?: number;\n    }) => Effect.Effect<Readonly<{\n        readonly collection: string;\n        readonly selected: number;\n        readonly embedded: number;\n        readonly failed: number;\n        readonly issues?: ReadonlyArray<string>;\n    }>, AuthoredRefusal>;\n};\n\ninterface CollectionQuery<S extends AnySchema, N extends TableName<S>> {\n    findMany(): Effect.Effect<Array<SchemaRow<S, N> & Readonly<Record<string, unknown>>>>;\n    findMany<const Config extends SchemaQueryConfig<S, N>>(config: ExactQueryInput<S, N, Config>): Effect.Effect<Array<SchemaQueryRow<S, N, Config> & Readonly<Record<string, unknown>>>>;\n    findFirst(): Effect.Effect<(SchemaRow<S, N> & Readonly<Record<string, unknown>>) | undefined>;\n    findFirst<const Config extends SchemaQueryConfig<S, N>>(config: ExactQueryInput<S, N, Config>): Effect.Effect<(SchemaQueryRow<S, N, Config> & Readonly<Record<string, unknown>>) | undefined>;\n    readonly count: (config?: Pick<SchemaQueryConfig<S, N>, 'where' | 'search'>) => Effect.Effect<number>;\n    /**\n     * The rows nearest a probe vector, closest first, each carrying its measured `distance`.\n     *\n     * Answered by the collection's vector index, so this stays exact and bounded as the collection\n     * grows: the same comparison done after reading rows would have to read all of them.\n     */\n    findNearest<const Col extends VectorColumnName<S, N>, const Config extends SchemaNearestConfig<S, N, Col>>(config: ExactConfig<Config, SchemaNearestConfig<S, N, Col>> & ExactWhereMember<Config> & {\n        readonly column: Col;\n    }): Effect.Effect<Array<SchemaQueryRow<S, N, Config> & Readonly<{\n        readonly distance: number;\n    }>>>;\n}\n\n/**\n * The declared write surface of one collection (RFC §4.2): only the operations its `+collection.ts`\n * declares exist, and each takes exactly the declared input. Every call is one transaction.\n */\nexport type CollectionWriteApi<S extends AnySchema, N extends TableName<S>, D> = ([\n    DeclaredCreate<D>\n] extends [never] ? Readonly<Record<never, never>> : Readonly<{\n    readonly create: (input: DeclaredCreate<D>) => Effect.Effect<SchemaRow<S, N>>;\n    readonly createMany: (inputs: ReadonlyArray<DeclaredCreate<D>>) => Effect.Effect<Array<SchemaRow<S, N>>>;\n}>) & ([DeclaredUpdate<D>] extends [never] ? Readonly<Record<never, never>> : Readonly<{\n    readonly update: (id: string, input: DeclaredUpdate<D>) => Effect.Effect<SchemaRow<S, N>>;\n    readonly updateMany: (inputs: ReadonlyArray<DeclaredUpdate<D> & {\n        readonly id: string;\n    }>) => Effect.Effect<Array<SchemaRow<S, N>>>;\n}>) & (DeclaresDelete<D> extends true ? Readonly<{\n    readonly delete: (id: string) => Effect.Effect<void>;\n    readonly deleteMany: (ids: ReadonlyArray<string>) => Effect.Effect<void>;\n}> : Readonly<Record<never, never>>);\n\nexport interface SchemaQueryConfig<S extends AnySchema, N extends TableName<S>> {\n    readonly where?: SchemaWhereFor<S, N>;\n    readonly search?: CollectionSearch;\n    readonly columns?: Partial<Readonly<Record<keyof SchemaRow<S, N>, boolean>>>;\n    readonly orderBy?: Partial<Readonly<Record<Exclude<keyof SchemaRow<S, N>, keyof SchemaReferences<S, N>>, 'asc' | 'desc'>>>;\n    readonly with?: Readonly<Partial<{\n        readonly [K in keyof SchemaReferences<S, N>]: SchemaReferences<S, N>[K] extends ReferenceTargets ? ReferenceQueryConfig<S, SchemaReferences<S, N>[K]> : never;\n    }> & Partial<{\n        readonly [K in keyof SchemaRelations<S, N>]: boolean | SchemaQueryConfig<S, RelationTarget<S, SchemaRelations<S, N>[K]>>;\n    }> & Record<string, boolean | Readonly<Record<string, unknown>>>>;\n    readonly limit?: number;\n}\n\nexport type CollectionPipelines<S extends AnySchema, N extends TableName<S>> = {\n    readonly export?: {\n        readonly description: string;\n        readonly handler: (context: {\n            readonly records: ReadonlyArray<SchemaRow<S, N>>;\n        }, api: Api<S>) => Effect.Effect<TExportManifest, AuthoredRefusal, never> | TExportManifest;\n    };\n    readonly import?: {\n        readonly description: string;\n        readonly input: Schema.Codec<unknown, unknown>;\n        readonly handler: (context: {\n            readonly input: unknown;\n        }, api: Api<S>) => Effect.Effect<ReadonlyArray<DeclaredCreate<DeclaredCollection<N>>>, AuthoredRefusal, never> | ReadonlyArray<DeclaredCreate<DeclaredCollection<N>>>;\n    };\n};"
		},
		{
			"title": "Automations",
			"body": "export type AutomationTrigger<S extends AnySchema = AnySchema> = \n/** No automatic trigger. The automation is still manually runnable, like every automation. */\n{\n    readonly schedule?: string;\n    readonly trigger?: never;\n} | {\n    /** An additional automatic start when a row changes. Manual invocation remains available. */\n    readonly trigger: {\n        readonly collection: TableName<S>;\n        readonly event: 'created' | 'updated' | 'deleted';\n    };\n    readonly schedule?: never;\n};\n\n/**\n * The capability an authored automation has in addition to the ordinary server API.\n *\n * It is deliberately absent from hooks and remotes. Progress belongs to a durable background run;\n * a hook is part of somebody else's atomic write and must never acquire an I/O checkpoint API that\n * can outlive or partially report that write.\n */\nexport type AutomationApi<S extends AnySchema = DefaultWorkspaceSchema> = Api<S> & NotifyApi & {\n    /**\n     * One-off sends on the declared channels, typed by each channel's transport. The message is\n     * committed to the channel outbox and delivered, retried and recorded there.\n     */\n    readonly channels: ChannelsApi;\n    /** `api.integrations.<name>.reconcile()`: a full reconcile of every sync the integration declares, queued. */\n    readonly integrations: IntegrationsApi;\n    /** Runtime-owned occurrence identity, stable across retries. Use it to key durable receipts. */\n    readonly runId: string;\n    /** Retrieves a bounded public HTTPS page through the host connector, without stored sign-ins. */\n    readonly readUrl: (url: string) => Effect.Effect<import('@norbital-ai/bolt-protocol').WebPage>;\n    /** Bounded GET through this automation's declared connection and managed credential. */\n    readonly connection: {\n        readonly get: (input: {\n            readonly path: string;\n            readonly query?: Readonly<Record<string, string | number | boolean>>;\n        }) => Effect.Effect<import('@norbital-ai/bolt-protocol').IntegrationHttpResponse>;\n    };\n    /** Replaces this run's current progress snapshot and advances its monotonic sequence. */\n    readonly progress: (value: AutomationProgression) => Effect.Effect<void>;\n};\n\nexport type AutomationContext<T extends AutomationTrigger<S>, S extends AnySchema, I extends Schema.Top | undefined = undefined> = {\n    readonly args: AutomationInput<I>;\n    readonly scope: T extends {\n        readonly trigger: {\n            readonly collection: infer N extends TableName<S>;\n        };\n    } ? {\n        readonly incoming_record: SchemaRow<S, N>;\n    } : Readonly<Record<string, unknown>>;\n};\n\nexport interface AutomationDefinition<S extends AnySchema = DefaultWorkspaceSchema, T extends AutomationTrigger<S> = AutomationTrigger<S>, I extends Schema.Top | undefined = undefined, O extends Schema.Top | undefined = undefined, E = never> {\n    readonly trigger: T;\n    readonly spec: Readonly<{\n        readonly description: string;\n        readonly connection?: HttpConnection;\n        /**\n         * The policies this automation runs under — its authority *and* its toolset.\n         *\n         * Required, and required for the reason `envoy()` requires them: an automation that names none\n         * would hold nothing, and the shape that let it hold whatever its trigger held is exactly what\n         * this replaces.\n         */\n        readonly policies: ReadonlyArray<PolicyName>;\n        readonly handler: (api: AutomationApi<S>, context: AutomationContext<T, S, I>) => Effect.Effect<AutomationOutput<O>, E, never> | AutomationOutput<O>;\n    }> & AutomationInputDeclaration<I> & AutomationOutputDeclaration<O>;\n}\n\n/**\n * Public call contract kept distinct from the implementation so declaration emission retains\n * `DefaultWorkspaceSchema`. Each workspace can therefore augment the handler's concrete tables\n * before TypeScript contextually types its incoming record and database API.\n */\ninterface DefineAutomation {\n    <S extends AnySchema = DefaultWorkspaceSchema, const T extends AutomationTrigger<S> = AutomationTrigger<S>, const I extends Schema.Top | undefined = undefined, const O extends Schema.Top | undefined = undefined, E = never>(trigger: ExactAutomationTrigger<T>, spec: AutomationDefinition<S, T, I, O, E>['spec']): AutomationDefinition<S, T, I, O, E>;\n}\n\nexport declare const defineAutomation: DefineAutomation;"
		},
		{
			"title": "Collections and notifications",
			"body": "/** The declaration `defineCollection` accepts. */\nexport interface CollectionDeclaration<M extends ModelDeclaration = ModelDeclaration, Create extends CollectionOperationDeclaration | undefined = undefined, Update extends CollectionOperationDeclaration | undefined = undefined, Delete extends Readonly<Record<never, never>> | undefined = undefined> {\n    readonly model: M;\n    /** Presence exposes `create`; absent, the collection accepts no direct create. */\n    readonly create?: Create;\n    /** Presence exposes `update`; absent, the collection accepts no direct update. */\n    readonly update?: Update;\n    /** Presence exposes `delete(id)`; a delete has no input and no transform. */\n    readonly delete?: Delete;\n    /** `NoInfer`: the transform is checked against the declaration, never a source of its generics. */\n    readonly transform?: NoInfer<CollectionTransform<M, (Create extends undefined ? never : CollectionInputOf<M, Create, 'create'>) | (Update extends undefined ? never : CollectionInputOf<M, Update, 'update'>)>>;\n    readonly notifications?: CollectionNotifications;\n    /** Similarity indexes, each a `/<name>` search command on this collection. */\n    readonly similarity?: Readonly<Record<string, SimilarityIndexDeclaration<M>>>;\n}\n\n/** The input selection one operation declares. */\nexport interface CollectionOperationDeclaration {\n    readonly input: CollectionInputSelection;\n}\n\n/**\n * One transform. It runs once per admitted batch, reads as the workspace, and returns one payload\n * per input, in order, or refuses. Returning the payload is how it asks for writes.\n */\nexport type CollectionTransform<M extends ModelDeclaration, Input> = (inputs: ReadonlyArray<Input>, context: Readonly<{\n    /** The stored root row per input, `undefined` on a create. */\n    readonly existing: ReadonlyArray<RowFor<M> | undefined>;\n    /** The reads-only tenant database surface, budgeted to two waves per operation. */\n    readonly db: CollectionTransformDatabase;\n}>) => Effect.Effect<ReadonlyArray<PayloadFor<M, 'create'> | PayloadFor<M, 'update'>>, AuthoredRefusal>;\n\n/** What every lifecycle event carries to its rules. */\nexport interface CollectionLifecycleEvent {\n    readonly event: CollectionNotificationEvent;\n    readonly collection: string;\n    readonly action: 'create' | 'update' | 'delete';\n    /** The ids of the records the operation wrote or held, root first. */\n    readonly ids: ReadonlyArray<string>;\n    /** The user who submitted the operation. */\n    readonly requestor: string;\n    /** The open request, on approval events. */\n    readonly approval?: Readonly<{\n        readonly requestId: string;\n        readonly step: Readonly<{\n            readonly index: number;\n            readonly approvers: ReadonlyArray<string>;\n        }>;\n        readonly decidedBy?: string;\n        readonly reason?: string;\n    }>;\n}\n\n/** The events every collection may notify on, one for each approval-machine transition. */\nexport type CollectionNotificationEvent = 'committed' | 'rejected' | 'approvalStarted' | 'approvalStepRequested' | 'approvalStepApproved' | 'approvalChangesRequested' | 'approvalWithdrawn' | 'approvalSuperseded' | 'approvalConflicted' | 'approvalCompleted';\n\n/**\n * One declared notification rule: a person channel, who, and what. The channel is one of the\n * workspace's declared channels that can reach a person (`inbox`, `email`, a chat); naming none is a\n * type error, and a workspace that declares none has no notification rules to write.\n */\nexport type CollectionNotificationRule = {\n    readonly channel: PersonChannel;\n    /** User ids, or `{ team }` for every member of a team — an approval step's approvers are teams. */\n    readonly recipients: (event: CollectionLifecycleEvent) => ReadonlyArray<NotificationRecipient>;\n    readonly message: (event: CollectionLifecycleEvent) => Readonly<{\n        readonly title: string;\n        readonly body: string;\n    }>;\n};\n\nexport type CollectionNotifications = Readonly<Partial<Record<CollectionNotificationEvent, ReadonlyArray<CollectionNotificationRule>>>>;\n\n/**\n * Who a notification is for: a user id, or `{ team }` — every member of that team at commit time,\n * resolved inside the write's own statement.\n */\nexport declare const NotificationRecipient: Schema.Union<readonly [Schema.NonEmptyString, Schema.Struct<{\n    readonly team: Schema.NonEmptyString;\n}>]>;"
		},
		{
			"title": "Channels",
			"body": "/** The outbound message a transport takes. */\nexport type MessageFor<T extends Transport> = T extends 'email' ? EmailMessage : T extends 'whatsapp' | 'telegram' ? ChatMessage : T extends 'inbox' ? InboxMessage : HttpRequest;\n\n/** The inbound envelope a transport delivers. */\nexport type EnvelopeFor<T extends Transport> = T extends 'email' ? EmailEnvelope : T extends 'http' ? HttpDelivery : ChatEnvelope;\n\n/** `api.channels.<name>.send`, one entry per declared channel, typed by its transport. */\nexport type ChannelsApi = {\n    readonly [N in ChannelName]: {\n        readonly send: (message: MessageFor<TransportOf[N]>) => import('effect').Effect.Effect<{\n            readonly outboxId: string;\n        }>;\n    };\n};\n\nexport type NotifyInput = Readonly<{\n    /** The notification's durable identity: one key is one notification however often it is stated. */\n    readonly key: string;\n    readonly recipients: ReadonlyArray<NotificationRecipient>;\n    readonly title: string;\n    readonly body: string;\n    /** Required and non-empty: no delivery is implied. */\n    readonly via: readonly [PersonChannel, ...PersonChannel[]];\n}>;\n\n/** `api.notify` exists only when the workspace declares a channel that can reach a person. */\nexport type NotifyApi = [PersonChannel] extends [never] ? {} : {\n    readonly notify: (notification: NotifyInput) => import('effect').Effect.Effect<void>;\n};\n\n/**\n * One outbound rule: a write to `from` sends a message on this channel.\n *\n * The message is built on the write path and committed to the channel outbox in the write's own\n * transaction, so a message means \"this happened\", and a crash after the commit leaves a queued\n * send, never a lost one. Pure and synchronous, like every per-record function on the write path.\n */\nexport type OutboundRule<S extends AnySchema, T extends Transport, N extends TableName<S>> = {\n    readonly from: N;\n    readonly on: OutboundTrigger<S, N>;\n    readonly message: (context: {\n        readonly record: SchemaRow<S, N>;\n        readonly previous?: SchemaRow<S, N>;\n    }) => MessageFor<T>;\n};\n\n/**\n * What the provider reports back about a message an outbound rule sent, as one patch on the record\n * that caused it. Only that record, and only the fields returned; `undefined` records nothing.\n */\nexport type ChannelEvents<S extends AnySchema, T extends Transport, N extends TableName<S>> = {\n    /** The relay accepted the message: it has left this workspace. Fired by the runtime, every transport. */\n    readonly sent?: (event: {\n        readonly at: string;\n    }) => Patch<S, N> | undefined;\n    readonly delivered?: (event: {\n        readonly at: string;\n    }) => Patch<S, N> | undefined;\n    readonly bounced?: (event: {\n        readonly at: string;\n        readonly reason: string;\n    }) => Patch<S, N> | undefined;\n    readonly opened?: (event: {\n        readonly at: string;\n    }) => Patch<S, N> | undefined;\n    readonly failed?: (event: {\n        readonly at: string;\n        readonly reason: string;\n    }) => Patch<S, N> | undefined;\n    readonly replied?: (event: {\n        readonly at: string;\n        readonly mail: EnvelopeFor<T>;\n    }) => Patch<S, N> | undefined;\n};\n\nexport type ChannelDefinition<T extends Transport = Transport, S extends AnySchema = DefaultWorkspaceSchema, N extends TableName<S> = TableName<S>> = {\n    readonly transport: T;\n    /** An email channel's local part (defaults to the channel name); the host mints the address. */\n    readonly address?: T extends 'email' ? string : never;\n    /** An `http` channel's endpoint. */\n    readonly connection?: T extends 'http' ? HttpConnection : never;\n    /** An `http` channel that also receives: how a delivery proves it came from the source. */\n    readonly webhook?: T extends 'http' ? {\n        readonly signature: WebhookSignatureSpec;\n        readonly eventIdHeader?: string;\n    } : never;\n    /** The authority outbound rules read and event patches write under. Required with either. */\n    readonly policies?: ReadonlyArray<PolicyName>;\n    readonly outbound?: Readonly<Record<string, OutboundRule<S, T, N>>>;\n    readonly events?: ChannelEvents<S, T, N>;\n};\n\n/**\n * Declares one channel: an instance of a transport. The file key is its name.\n *\n * Validation runs at module load, so a malformed channel fails `bolt sync` naming its file.\n */\nexport declare const defineChannel: <const T extends Transport, S extends AnySchema = DefaultWorkspaceSchema, const N extends TableName<S> = TableName<S>>(declaration: ChannelDefinition<T, S, N>) => ChannelDefinition<T, S, N>;\n\nexport declare const ChatMessage: Schema.Struct<{\n    readonly to: Schema.NonEmptyString;\n    readonly text: Schema.NonEmptyString;\n    readonly attachments: Schema.optionalKey<Schema.$Array<Schema.Union<readonly [Schema.Struct<{\n        readonly key: Schema.NonEmptyString;\n        readonly name: Schema.NonEmptyString;\n        readonly mimeType: Schema.NonEmptyString;\n    }>, Schema.Struct<{\n        readonly name: Schema.NonEmptyString;\n        readonly mimeType: Schema.NonEmptyString;\n        readonly contentBase64: Schema.String;\n    }>]>>>;\n}>;\n\nexport declare const EmailMessage: Schema.Struct<{\n    readonly to: Schema.$Array<Schema.NonEmptyString>;\n    readonly cc: Schema.optionalKey<Schema.$Array<Schema.NonEmptyString>>;\n    readonly subject: Schema.NonEmptyString;\n    readonly html: Schema.optionalKey<Schema.String>;\n    readonly text: Schema.optionalKey<Schema.String>;\n    readonly attachments: Schema.optionalKey<Schema.$Array<Schema.Union<readonly [Schema.Struct<{\n        readonly key: Schema.NonEmptyString;\n        readonly name: Schema.NonEmptyString;\n        readonly mimeType: Schema.NonEmptyString;\n    }>, Schema.Struct<{\n        readonly name: Schema.NonEmptyString;\n        readonly mimeType: Schema.NonEmptyString;\n        readonly contentBase64: Schema.String;\n    }>]>>>;\n    /** A thread key: replies in-thread when it names a thread this channel has seen or started. */\n    readonly thread: Schema.optionalKey<Schema.NonEmptyString>;\n}>;\n\nexport declare const InboxMessage: Schema.Struct<{\n    readonly recipients: Schema.$Array<Schema.Union<readonly [Schema.NonEmptyString, Schema.Struct<{\n        readonly team: Schema.NonEmptyString;\n    }>]>>;\n    readonly title: Schema.NonEmptyString;\n    readonly body: Schema.String;\n}>;\n\nexport declare const HttpRequest: Schema.Struct<{\n    readonly method: Schema.Literals<readonly [\"GET\", \"POST\", \"PUT\", \"PATCH\", \"DELETE\"]>;\n    readonly path: Schema.String;\n    readonly query: Schema.optionalKey<Schema.$Record<Schema.String, Schema.String>>;\n    readonly body: Schema.optionalKey<Schema.Codec<Schema.Json, Schema.Json, never, never>>;\n}>;"
		},
		{
			"title": "Integrations",
			"body": "/** How a source pages: a token read back and sent as a query, numbered pages, offsets, or `Link`. */\nexport type PageSpec = {\n    readonly query: string;\n    readonly next: NextPage;\n    readonly max?: number;\n} | {\n    readonly pageQuery: string;\n    readonly sizeQuery?: string;\n    readonly size?: number;\n    readonly firstPage?: number;\n    readonly max?: number;\n} | {\n    readonly offsetQuery: string;\n    readonly limitQuery: string;\n    readonly size: number;\n    readonly max?: number;\n} | {\n    readonly linkHeader: true;\n    readonly max?: number;\n};\n\nexport type ListSpec = Request;\n\nexport type ChangesSpec = Request & {\n    /** Where the kept cursor is sent, and where the next one is read from. */\n    readonly cursor: {\n        readonly send: {\n            readonly query: string;\n        } | {\n            readonly header: string;\n        };\n        readonly next: {\n            readonly header: string;\n        } | {\n            readonly field: string;\n        } | {\n            readonly maxOf: string;\n        };\n    };\n};\n\n/** The HTTP source capabilities a sync can use; `list`, `identity` and `record` are required. */\nexport type HttpRecordsSpec<R> = {\n    readonly list: ListSpec;\n    readonly changes?: ChangesSpec;\n    readonly subscribe?: {\n        readonly webhook: {\n            readonly signature: WebhookSignatureSpec;\n            /** A dotted path to the records a delivery carries; omitted when the body is one record. */\n            readonly records?: string;\n        };\n    };\n    readonly get?: {\n        readonly path: string;\n    };\n    readonly create?: Write;\n    readonly update?: Write;\n    readonly delete?: Write;\n    /** The source's key field (dotted). */\n    readonly identity: string;\n    /** The source's version field (dotted): an etag, `updated_at`, a revision. */\n    readonly version?: string;\n    /** A field (dotted) whose truthy value marks a record deleted at the source. */\n    readonly deleted?: string;\n    /**\n     * Where a create carries its idempotency key (the local row id). `field` means the source stores\n     * it, so a reconcile can match a create whose answer was lost.\n     */\n    readonly idempotencyKey?: {\n        readonly header: string;\n    } | {\n        readonly field: string;\n    };\n    /** The schema of one remote record, decoded per record so one bad record is one rejection. */\n    readonly record: Schema.Codec<R, unknown>;\n};\n\n/**\n * One mapping read both ways. A string names the remote field; an object translates. A mapping\n * with only `in` is never pushed: the remote owns that field.\n */\nexport type FieldMapping<S extends AnySchema, N extends TableName<S>, K extends ColumnOf<S, N>, R, Resolved> = RemoteField<R> | {\n    readonly in: (remote: R, context: {\n        readonly resolve: Resolved;\n    }) => ColumnValue<S, N, K>;\n    readonly out?: (local: ColumnValue<S, N, K>) => unknown;\n    /** The remote field `out` writes; required with `out`. */\n    readonly field?: RemoteField<R>;\n};\n\nexport type ConflictRule = 'remote_wins' | 'local_wins' | 'latest';\n\nexport type OneWaySync<S extends AnySchema, N extends TableName<S>, R, Resolved> = CommonSync<S, N, R, Resolved> & {\n    readonly direction: 'one_way';\n    readonly source: Source<R, 'list'>;\n};\n\nexport type TwoWaySync<S extends AnySchema, N extends TableName<S>, R, Resolved> = CommonSync<S, N, R, Resolved> & {\n    readonly direction: 'two_way';\n    /** Two-way needs create, update and delete: a source without them is a compile error. */\n    readonly source: Source<R, 'list' | 'create' | 'update' | 'delete'>;\n    /** Fields only one side may change; the other side's writes to them are refused. */\n    readonly owns?: {\n        readonly remote?: ReadonlyArray<ColumnOf<S, N>>;\n        readonly local?: ReadonlyArray<ColumnOf<S, N>>;\n    };\n    /** Required: every two-way sync states who wins a shared field changed on both sides. */\n    readonly conflicts: ConflictRule | {\n        readonly default: ConflictRule;\n        readonly fields: {\n            readonly [K in ColumnOf<S, N>]?: ConflictRule;\n        };\n    };\n    /** A delete on one side against an edit on the other. Defaults to `delete_wins`. */\n    readonly deletes?: 'delete_wins' | 'edit_wins';\n    /** Local rows the first sync never matched. Defaults to `report`. */\n    readonly onUnmatchedLocal?: 'push' | 'keep' | 'report';\n};\n\n/**\n * One integration: its sync subject's policies and one sync per collection. `T` maps each synced\n * collection to its source's record type, inferred from the `source` each sync names — so a field\n * mapping reads the remote record's own type, and a named remote field must exist on it.\n */\nexport type IntegrationDefinition<S extends AnySchema = DefaultWorkspaceSchema, T = Readonly<Record<string, unknown>>> = {\n    /** The complete authority the sync subject `integration:<name>` holds. */\n    readonly policies: ReadonlyArray<PolicyName>;\n    readonly syncs: {\n        readonly [N in keyof T]: SyncDefinition<S, N & TableName<S>, T[N], unknown>;\n    };\n};\n\n/**\n * Declares one integration. The type checks each sync against its collection and source; the\n * runtime checks what types cannot (dotted remote fields, the identity index) at `bolt sync`.\n */\nexport declare const defineIntegration: <S extends AnySchema = DefaultWorkspaceSchema, T extends { readonly [K in TableName<S>]?: unknown; } = {}>(definition: IntegrationDefinition<S, T>) => IntegrationDefinition<S, T>;\n\nexport declare const http: {\n    /** One connection to an HTTP API, declared once for every sync against it. */\n    source: <const Connection extends HttpConnection>(connection: Connection) => {\n        records: <R, const Spec extends HttpRecordsSpec<R>>(spec: Spec & HttpRecordsSpec<R>) => Source<R, CapabilitiesOf<Spec>>;\n    };\n};\n\n/**\n * A declared channel's message stream as a source: `list` is its history, `subscribe` is live\n * ingest, edits and deletes are changes. Always one-way.\n */\nexport declare const channel: <const N extends ChannelName>(name: N) => {\n    messages: (options?: {\n        readonly inbound?: boolean;\n    }) => Source<EnvelopeFor<TransportOf[N]> & {\n        readonly direction: \"inbound\" | \"outbound\";\n    }, \"list\" | \"subscribe\">;\n};"
		},
		{
			"title": "Model columns",
			"body": "/** What an instant-range renderer offers: calendar days, or date-times. */\nexport declare const defineModel: <const TColumns extends Readonly<Record<string, AnyModelFieldBuilder>>>(columns: TColumns, metadata?: ModelMetadata) => ModelDeclaration<TColumns>;\n\n/**\n * What a `defineModel` declaration may say about the collection as a whole.\n *\n * Every key here is read by something; an option nothing reads is a lie in the authoring surface, so\n * The authoring surface accepts no `opsGuard`, `replica` or `insertOnly` field: they have no\n * reference anywhere in this package and no declaration in any template — accepting them only bought\n * an author the belief that a flag had an effect.\n *\n * `tests/authoring/metadata-witness.test.ts` holds this interface against the function that reads\n * each key, so a key added here has to name its reader or be listed as knowingly unread.\n */\nexport interface ModelMetadata {\n    readonly description?: string;\n    /**\n     * The column, or columns, that name a record on screen.\n     *\n     * The array form compiles to the ` + ' · ' + ` concatenation `resolveRecordLabel` splits on, so a\n     * label survives term by term when one field is empty rather than collapsing to a uuid.\n     */\n    readonly recordLabel?: string | ReadonlyArray<string>;\n    readonly icon?: string;\n    readonly history?: boolean;\n    readonly indexes?: ReadonlyArray<ModelIndex>;\n    readonly exclusions?: ReadonlyArray<ModelExclusion>;\n    /** The searchable columns' embedding model, or `false` for lexical-only. See `ModelEmbedding`. */\n    readonly embedding?: ModelEmbedding | false;\n}\n\n/**\n * The model behind a collection's record embedding, chosen once for the whole collection.\n *\n * Which columns feed the vector is not declared here: every column marked `search: true` does —\n * text contributes its words, a `file()` its image — beside the deterministic lexical document the\n * same mark builds. Declare this only when the host's default embedding model will not do (an image\n * needs a multimodal model), or `false` to keep the collection's search lexical.\n */\nexport interface ModelEmbedding {\n    /** The embeddings model; the host's configured default when absent. */\n    readonly model?: string;\n    /** Matryoshka truncation and the vector column's width; 256 when absent. */\n    readonly dimensions?: number;\n}\n\nexport declare const text: (options?: {\n    readonly search?: boolean;\n}) => import(\"drizzle-orm/pg-core\").PgTextBuilder<[string, ...string[]]>;\n\nexport declare const numeric: () => import(\"drizzle-orm/pg-core\").PgNumericNumberBuilder;\n\n/** Owns the only temporal scalar at the authoring boundary. */\nexport declare const instant: (options?: {\n    readonly precision?: InstantPrecision;\n}) => import(\"drizzle-orm/pg-core\").PgTimestampStringBuilder;\n\n/** Owns enums behavior at the authoring boundary so validation and typed semantics stay consistent for every caller. */\nexport declare const enums: (values: readonly [string, ...string[]], options?: {\n    readonly search?: boolean;\n}) => import(\"drizzle-orm/pg-core\").PgTextBuilder<[string, ...string[]]>;\n\n/** Owns file behavior at the authoring boundary so validation and typed semantics stay consistent for every caller. */\nexport declare const file: typeof fileColumn;\n\n/** Owns vector behavior at the authoring boundary so validation and typed semantics stay consistent for every caller. */\nexport declare const vector: (options: {\n    readonly dimensions: number;\n}) => import(\"drizzle-orm/pg-core\").PgVectorBuilder;\n\n/**\n * Declares one logical field that may point at exactly one of the named collections.\n *\n * Tags are the stable application discriminator; collection names are the physical FK targets.\n * The database representation is generated later and never leaks into authored row types.\n */\nexport declare const reference: <const TTargets extends ReferenceTargets>(targets: TTargets) => ReferenceBuilder<TTargets, false, false>;\n\nexport declare const custom: <const Name extends CustomTypeName, const Arguments extends CustomArguments<Name>>(name: Name, ...arguments_: Arguments) => import(\"drizzle-orm/pg-core\").Set$Type<import(\"drizzle-orm/pg-core\").PgJsonbBuilder, CustomColumnValue<Name, Arguments[0]>>;\n\nexport declare const group: <const T extends BoltGroupDefinition>(definition: T) => T;\n\nexport declare const cascade: <T extends object>(relationship: T) => T;\n\nexport declare const setNull: <T extends object>(relationship: T) => T;\n\nexport declare const deferrable: <T extends object>(relationship: T) => T;\n\n/** Owns geolocation behavior at the authoring boundary so validation and typed semantics stay consistent for every caller. */\nexport declare const geolocation: () => import(\"drizzle-orm/pg-core\").Set$Type<import(\"drizzle-orm/pg-core\").PgJsonbBuilder, {\n    readonly geometry: {\n        readonly lon: number;\n        readonly lat: number;\n    } | null;\n    readonly formatted_address: string;\n    readonly type: \"Point\";\n    readonly srid: number;\n}>;\n\n/** Owns phone behavior at the authoring boundary so validation and typed semantics stay consistent for every caller. */\nexport declare const phone: (options?: {\n    readonly search?: boolean;\n}) => import(\"drizzle-orm/pg-core\").PgTextBuilder<[string, ...string[]]>;\n\n/**\n * Refuses the operation, and is declared to return `never` explicitly.\n *\n * The annotation is load-bearing, not decoration. TypeScript only treats a call as terminating\n * control flow when the callee is an identifier carrying an **explicit** return type, so without it\n * `if (value == null) refuse('…')` narrows nothing and every use below the guard is\n * `possibly undefined`. The emitted `.d.ts` infers one, which is why a workspace compiling against\n * the published build behaved differently from one compiling against these sources — 32 phantom\n * errors in a single template, none of them the template's fault.\n */\nexport declare const refuse: (message: string) => never;"
		},
		{
			"title": "Policies, approvals, teams",
			"body": "/**\n * A policy: the complete statement of what its holder may do.\n *\n * Four keys, and every one answers a question about *this policy's holders* — whether that holder is\n * a person through a team, an envoy, or an automation. `grants` is what they may touch,\n * `capabilities` is what they may call, `limits` is how much, and the approval on a grant is who has\n * to agree first. Nothing else in the system grants capability.\n *\n * There is no `name`. The filename is the name, exactly as it is for a collection, an app and an\n * envoy, and a restated `name:` is precisely what let five workspaces ship a display-cased string\n * that compiled and matched nothing. There is no field left to disagree with the file.\n */\nexport interface PolicyDefinition<S extends AnySchema = DefaultWorkspaceSchema> {\n    readonly description: string;\n    readonly grants: PolicyGrants<S>;\n    readonly capabilities?: PolicyCapabilities;\n    readonly limits?: PolicyLimits;\n}\n\n/**\n * What write authorization and approval-flow functions may reach: collection reads.\n *\n * Deciding whether a write may proceed or who must sign it is evaluated through the direct\n * `db.<collection>` route.\n */\nexport type PolicyDecisionApi<S extends AnySchema = DefaultWorkspaceSchema> = Readonly<{\n    readonly db: AuthoredReadDatabase<S>;\n    readonly requestor: Readonly<{\n        readonly id: string;\n        readonly userId: string;\n        readonly tenantId: string;\n        readonly email?: string;\n        readonly team?: TeamName;\n        readonly teamPath: ReadonlyArray<TeamName>;\n        readonly admin: boolean;\n    }>;\n}>;\n\nexport type ApprovalFlow = ApprovalReviewFlow | NoApprovalFlow;\n\nexport type ApprovalReviewFlow = Readonly<{\n    readonly _tag: 'Review';\n    readonly stages: ReadonlyArray<ApprovalStage>;\n    readonly thenBy: (first: TeamName, ...others: ReadonlyArray<TeamName>) => ApprovalReviewFlow;\n    readonly [ApprovalFlowBrand]: true;\n}>;\n\nexport type NoApprovalFlow = Readonly<{\n    readonly _tag: 'NoApproval';\n    readonly [ApprovalFlowBrand]: true;\n}>;\n\n/**\n * The shape of `src/access/+teams.ts`: which policies each named team holds.\n *\n * Keys are team names, matched case-insensitively against `team.name`, and free strings on\n * purpose — a team is a row an operator creates from a dashboard, so no compiled union can enumerate\n * them, and this file is where the enumeration comes from. Values are narrowed to *this* workspace's\n * declared policy names, so renaming or deleting a policy breaks the build here, in the map that\n * hands it to people, instead of quietly emptying somebody's authority at run time.\n *\n * The runtime is deliberately more forgiving than this type: a team naming a policy the release does\n * not declare has that name dropped and warned about, never refused, because a row and a release\n * move independently and a workspace must not fall over on a stale string. This check is what makes\n * that tolerance a safety net rather than the only line of defence.\n */\nexport type Teams = Readonly<Record<string, ReadonlyArray<PolicyName>>>;\n\n/** Starts a concrete review flow. Teams listed in one stage are alternatives; stages are sequential. */\nexport declare const approveBy: (first: TeamName, ...others: ReadonlyArray<TeamName>) => ApprovalReviewFlow;\n\n/** Explicitly selects the branch in which this write needs no review. */\nexport declare const noApproval: NoApprovalFlow;"
		},
		{
			"title": "Functions",
			"body": "/** Public read-remote contract that retains the augmented workspace schema in generated types. */\ninterface DefineQueryHandler {\n    <const S extends Schema.Codec<unknown, unknown>, Workspace extends AnySchema = DefaultWorkspaceSchema, Output = unknown, E = never>(definition: AuthoredHandler<S, Workspace, Output, E>): HandlerDefinition<S, Output, Workspace, 'query', E>;\n}\n\n/**\n * Public mutating-remote contract. The literal command discriminant is part of compiler discovery\n * and runtime authorization, while the symbolic default lets each workspace augment its tables.\n */\ninterface DefineCommandHandler {\n    <const S extends Schema.Codec<unknown, unknown>, Workspace extends AnySchema = DefaultWorkspaceSchema, Output = unknown, E = never>(definition: AuthoredHandler<S, Workspace, Output, E>): HandlerDefinition<S, Output, Workspace, 'command', E>;\n}\n\nexport declare const defineQueryHandler: DefineQueryHandler;\n\nexport declare const defineCommandHandler: DefineCommandHandler;"
		}
	];
